// spec: specs/business-cards-images.md (1.1–1.4) · кейсы: .qa/tests/business-cards-images/CARDIMG-01..05.md
// Гость, прод, только просмотр. Карточки не привязаны к объявлениям — проверяются все показанные.
// Устройства: @desktop (1440×900) и @android (Pixel 7, сценарий клиента) — отдельными тестами.
import { test, expect } from '@playwright/test';
import {
  prepare, openCards, loadFirst, readCards, visibleImg, originalOf, naturalSizes, padding,
  expectUncropped, expectWindow43, isNeutralLight, STONE_50, Card,
} from './cards.helpers';

const PAGES = [
  { path: '/search' as const, name: '/search' },
  { path: '/' as const, name: 'главная' },
];
const DEVICES = ['@desktop', '@android'];

for (const dev of DEVICES) {
  for (const p of PAGES) {
    test.describe(`Картинки карточек — ${p.name} ${dev}`, () => {
      test.beforeEach(async ({ page }) => {
        await prepare(page);
        await openCards(page, p.path);
      });

      test(`${p.name}: картинки карточек целиком — contain без cover, файл .card2.webp #0a2499 ${dev} @prod-safe`, async ({ page }) => {
        const cards = await readCards(page);
        expectUncropped(cards, p.name);
      });

      test(`${p.name}: .card2.webp в пропорциях оригинала, поля по нужной оси #0a2499 ${dev} @prod-safe`, async ({ page }) => {
        await loadFirst(page, 40);
        const loaded = (await readCards(page)).filter((c) => !c.video && c.imgs.length && visibleImg(c).nat[0] > 0);
        const ratio = (c: Card) => visibleImg(c).nat[0] / visibleImg(c).nat[1];
        const vertical = loaded.filter((c) => ratio(c) < 0.95);
        const wide = loaded.filter((c) => ratio(c) > 1.4);
        const rest = loaded.filter((c) => !vertical.includes(c) && !wide.includes(c));
        expect(vertical.length, `${p.name}: среди первых карточек есть вертикальная картинка`).toBeGreaterThan(0);
        const sample = [...vertical.slice(0, 5), ...wide.slice(0, 3)];
        sample.push(...rest.slice(0, 12 - sample.length));

        const origs = await naturalSizes(page, sample.map((c) => originalOf(visibleImg(c).src)));
        sample.forEach((c, k) => {
          const img = visibleImg(c);
          const o = origs[k];
          const label = `${p.name}, карточка ${c.idx} (${img.nat.join('×')})`;
          expect(o, `${label}: оригинал загрузился`).not.toBeNull();
          const rCard = img.nat[0] / img.nat[1];
          const rOrig = o![0] / o![1];
          expect(Math.abs(rCard - rOrig) / rOrig, `${label}: пропорция card2 ${rCard.toFixed(3)} ≈ оригиналу ${o!.join('×')}`).toBeLessThanOrEqual(0.02);

          const pad = padding(c, img);
          if (rCard < (4 / 3) * 0.98) {
            expect(pad.y, `${label}: узкая — сверху/снизу без полей`).toBeLessThanOrEqual(1);
            expect(pad.x, `${label}: узкая — поля слева/справа`).toBeGreaterThan(1);
          } else if (rCard > (4 / 3) * 1.02) {
            expect(pad.x, `${label}: широкая — слева/справа без полей`).toBeLessThanOrEqual(1);
            expect(pad.y, `${label}: широкая — поля сверху/снизу`).toBeGreaterThan(1);
          } else {
            expect(Math.max(pad.x, pad.y), `${label}: 4:3 — без заметных полей`).toBeLessThanOrEqual(3);
          }
        });
      });

      test(`${p.name}: окно медиа 4:3 во всю ширину, фон полей нейтральный #0a2499 ${dev} @prod-safe`, async ({ page }) => {
        const cards = await readCards(page);
        expectWindow43(cards, p.name);
        for (const c of cards) {
          // Карусель «מודעות מומלצות» на главной — stone-100 (находка 2026-11-04), там только «нейтральный светлый».
          if (/מודעות מומלצות/.test(c.section)) expect(isNeutralLight(c.bg), `${p.name}, карточка ${c.idx} (${c.section}): фон ${c.bg} нейтральный`).toBe(true);
          else expect(c.bg, `${p.name}, карточка ${c.idx}: фон полей stone-50`).toBe(STONE_50);
        }
      });

      if (p.path === '/search') {
        test(`/search: видео в карточке на всё окно (cover), без полос #0a2499 #464adb ${dev} @prod-safe`, async ({ page }) => {
          const videos = (await readCards(page)).filter((c) => c.video);
          expect(videos.length, '/search: есть карточка с видео').toBeGreaterThan(0);
          for (const c of videos) {
            expect(c.video!.fit, `/search, карточка ${c.idx}: видео object-fit`).toBe('cover');
            expect(Math.abs(c.video!.w - c.box[2]), `/search, карточка ${c.idx}: ширина видео = окну`).toBeLessThanOrEqual(1);
            expect(Math.abs(c.video!.h - c.box[3]), `/search, карточка ${c.idx}: высота видео = окну`).toBeLessThanOrEqual(1);
          }
        });
      }
    });
  }
}
